// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"Como usar este guia","html":"<p>Este guia faz parte da formação da equipe para o uso da plataforma de reforço escolar da rede municipal. Ele pode ser lido de uma vez ou consultado por capítulo, quando surgir uma dúvida.</p><h3>Ao final, você será capaz de</h3><ul><li>Explicar à equipe e aos responsáveis como o reforço funciona.</li><li>Aplicar diagnósticos e ler as habilidades prioritárias (coordenação).</li><li>Organizar turmas, professores e acessos da escola (direção).</li><li>Entregar o acesso aos responsáveis e acompanhar a adesão.</li><li>Ler os indicadores de prática e de recuperação de habilidades.</li><li>Conduzir uma reunião pedagógica com base nos dados.</li><li>Usar a plataforma com ética e proteger os dados dos alunos.</li></ul><h3>Como estudar</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que fazer</th><th>Tempo</th></tr></thead><tbody><tr><td data-rotulo=\"Etapa\">Leitura</td><td data-rotulo=\"O que fazer\">Ler os capítulos 2 a 10 e acompanhar as figuras.</td><td data-rotulo=\"Tempo\">2 h 30</td></tr><tr><td data-rotulo=\"Etapa\">Prática</td><td data-rotulo=\"O que fazer\">Repetir os exemplos na plataforma, com os dados da sua escola.</td><td data-rotulo=\"Tempo\">2 h</td></tr><tr><td data-rotulo=\"Etapa\">Ética e dados</td><td data-rotulo=\"O que fazer\">Ler os capítulos 12 e 13.</td><td data-rotulo=\"Tempo\">45 min</td></tr><tr><td data-rotulo=\"Etapa\">Verificação</td><td data-rotulo=\"O que fazer\">Responder às questões do capítulo 15.</td><td data-rotulo=\"Tempo\">45 min</td></tr></tbody></table></div><div class=\"nota\"><b>Dados dos exemplos</b><br/>Os nomes, as turmas e os números usados nos exemplos e nos gráficos deste guia são fictícios. Eles servem para mostrar como ler as telas.</div>"},{"id":"c2","titulo":"O papel da gestão no reforço","html":"<p>O reforço funciona sozinho para o aluno. A gestão garante as condições: turmas e professores organizados, responsáveis com acesso e acompanhamento dos resultados.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Perfil</th><th>Responsabilidade principal</th><th>O que enxerga</th></tr></thead><tbody><tr><td data-rotulo=\"Perfil\">Coordenação pedagógica</td><td data-rotulo=\"Responsabilidade principal\">Diagnósticos, trilhas da rede e habilidades prioritárias.</td><td data-rotulo=\"O que enxerga\">As escolas vinculadas à sua coordenação.</td></tr><tr><td data-rotulo=\"Perfil\">Direção escolar</td><td data-rotulo=\"Responsabilidade principal\">Turmas, alunos, professores e acesso dos responsáveis.</td><td data-rotulo=\"O que enxerga\">A sua escola.</td></tr></tbody></table></div><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Organizar</b><small>turmas, alunos e professores</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Entregar</b><small>acessos a alunos e responsáveis</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Diagnosticar</b><small>aplicar o diagnóstico</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Acompanhar</b><small>prática e recuperação</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Agir</b><small>apoiar turmas e professores</small></div></div><figcaption>Figura. O trabalho da gestão ao longo do ano.</figcaption></figure>"},{"id":"c3","titulo":"Como o aluno estuda","html":"<p>O reforço é individual. Cada aluno entra com o próprio acesso, escolhe a matéria que quer estudar e segue um caminho montado para ele, em casa ou na escola, no tablet, no celular ou no computador.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Entrar</b><small>acesso individual entregue pela escola</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Diagnóstico</b><small>questões curtas por habilidade</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Trilha</b><small>cinco etapas por habilidade</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Tutor</b><small>dicas e perguntas, sem dar a resposta</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Evolução</b><small>três níveis de domínio</small></div></div><figcaption>Figura. O caminho do aluno no reforço.</figcaption></figure><h3>O diagnóstico</h3><p>O diagnóstico usa poucas questões por habilidade e para assim que tem segurança sobre o que o aluno sabe. Não é prova, não gera nota e não aparece para o aluno como aprovação ou reprovação.</p><h3>A trilha em cinco etapas</h3><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Relembrar</b><small>retoma o que o aluno já viu</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Exemplo guiado</b><small>mostra a resolução passo a passo</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Praticar</b><small>questões com retorno imediato</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Aplicar</b><small>situações do dia a dia</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Explicar</b><small>o aluno explica com as próprias palavras</small></div></div><figcaption>Figura. As cinco etapas de cada trilha.</figcaption></figure><p>Cada resposta errada indica um tipo de dificuldade. A plataforma usa essa informação para escolher a dica e a próxima questão, em vez de apenas marcar certo ou errado.</p><h3>Os três níveis</h3><figure><div class=\"niveis\"><div class=\"nv\" style=\"background:#C44536\"><b>Ainda não</b><small>não mostrou domínio</small></div><div class=\"seta\">&#8250;</div><div class=\"nv\" style=\"background:#D9920B\"><b>Quase lá</b><small>acerta parte, precisa praticar</small></div><div class=\"seta\">&#8250;</div><div class=\"nv\" style=\"background:#1E8E5A\"><b>Domina</b><small>domínio consistente</small></div></div><figcaption>Figura. A evolução do aluno em cada habilidade.</figcaption></figure><h3>A volta ao que ficou para trás</h3><p>Muitas dificuldades vêm de um conteúdo de ano anterior. Quando o aluno erra, a plataforma verifica as habilidades que servem de base e leva o aluno a elas antes de seguir.</p><figure><div class=\"escada\"><div class=\"dg\" style=\"margin-left:0mm\"><span class=\"ano\">6º ano</span><span class=\"hab\">Resolver problemas com frações</span><span class=\"sit sn\">Ainda não</span></div><div class=\"dg\" style=\"margin-left:9mm\"><span class=\"ano\">5º ano</span><span class=\"hab\">Comparar e ordenar frações</span><span class=\"sit sq\">Quase lá</span></div><div class=\"dg\" style=\"margin-left:18mm\"><span class=\"ano\">4º ano</span><span class=\"hab\">Reconhecer frações unitárias</span><span class=\"sit sd\">Domina</span></div></div><figcaption>Figura. Exemplo: a dificuldade do 6º ano tem origem em uma habilidade do 5º ano. O aluno estuda primeiro a do 5º.</figcaption></figure><div class=\"nota\"><b>O reforço não depende da aula</b><br/>Ninguém da escola precisa liberar, aplicar ou corrigir nada para o reforço acontecer. A escola oferece o acesso e acompanha.</div>"},{"id":"c4","titulo":"Coordenação pedagógica: o seu menu","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>No menu</th><th>Para que serve</th><th>Quando usar</th></tr></thead><tbody><tr><td data-rotulo=\"No menu\">Visão geral</td><td data-rotulo=\"Para que serve\">Resumo de diagnósticos, trilhas e habilidades da rede.</td><td data-rotulo=\"Quando usar\">Sempre que entrar.</td></tr><tr><td data-rotulo=\"No menu\">Diagnósticos</td><td data-rotulo=\"Para que serve\">Identificação das lacunas por turma, com diagnósticos prontos e os criados pela rede.</td><td data-rotulo=\"Quando usar\">No início do ano e a cada bimestre.</td></tr><tr><td data-rotulo=\"No menu\">Trilhas</td><td data-rotulo=\"Para que serve\">Aprovação das trilhas criadas pelos professores e biblioteca da rede.</td><td data-rotulo=\"Quando usar\">Todo mês.</td></tr><tr><td data-rotulo=\"No menu\">Habilidades prioritárias</td><td data-rotulo=\"Para que serve\">Habilidades com mais alunos em Ainda não.</td><td data-rotulo=\"Quando usar\">Toda semana.</td></tr><tr><td data-rotulo=\"No menu\">Escolas e turmas</td><td data-rotulo=\"Para que serve\">Participação e reforço em cada escola da sua coordenação.</td><td data-rotulo=\"Quando usar\">Toda semana.</td></tr><tr><td data-rotulo=\"No menu\">Retorno das famílias</td><td data-rotulo=\"Para que serve\">O que os responsáveis disseram sobre os professores.</td><td data-rotulo=\"Quando usar\">Todo mês.</td></tr><tr><td data-rotulo=\"No menu\">Formação</td><td data-rotulo=\"Para que serve\">Este guia e os demais materiais de treinamento.</td><td data-rotulo=\"Quando usar\">Em caso de dúvida.</td></tr></tbody></table></div><div class=\"nota\"><b>Nenhuma escola apareceu?</b><br/>O vínculo entre a coordenação e as escolas é feito pelo gestor da rede, na Secretaria. Peça a ele para vincular as escolas à sua coordenação.</div>"},{"id":"c5","titulo":"Diagnósticos e habilidades prioritárias","html":"<p>O diagnóstico é o ponto de partida. A plataforma traz diagnósticos prontos, alinhados à BNCC. A coordenação escolhe um e abre para a rede.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Escolher</b><small>um diagnóstico pronto ou criar um</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Abrir para a rede</b><small>as turmas passam a ver</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Alunos respondem</b><small>em casa ou na escola</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Ler o resultado</b><small>habilidades prioritárias</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Agir</b><small>trilhas e formação</small></div></div><figcaption>Figura. Do diagnóstico à ação.</figcaption></figure><figure><div class=\"tela\"><div class=\"barra\"><span></span><span></span><span></span><em>{{REDE}}</em></div><div class=\"app\"><aside><div class=\"logo\">{{REDE}}</div><div class=\"pf\">Coordenação pedagógica</div><div class=\"it\">Visão geral</div><div class=\"it at\">Diagnósticos</div><div class=\"it\">Trilhas</div><div class=\"it\">Habilidades prioritárias</div><div class=\"it\">Escolas e turmas</div><div class=\"it\">Retorno das famílias</div><div class=\"it\">Formação</div></aside><main><div class=\"cab\"><b>Diagnósticos</b><small>Identifique lacunas BNCC por turma</small></div><div class=\"corpo\"><div class=\"lst\"><div class=\"li\"><b>Matemática · 6º ano</b><small>Diagnóstico pronto, alinhado à BNCC</small><span class=\"bt\">Abrir para a rede</span></div><div class=\"li\"><b>Língua Portuguesa · 6º ano</b><small>Diagnóstico pronto, alinhado à BNCC</small><span class=\"bt\">Abrir para a rede</span></div><div class=\"li\"><b>Ciências · 7º ano</b><small>Criado pela rede</small><span class=\"bt\">Abrir</span></div></div></div></main></div></div><figcaption>Ilustração da tela. A coordenação escolhe o diagnóstico e abre para a rede.</figcaption></figure><h3>Habilidades prioritárias</h3><p>A tela mostra as habilidades com mais alunos em Ainda não. É a lista do que a rede precisa retomar e o melhor insumo para a formação de professores.</p><figure><div class=\"barras\"><div class=\"ln\"><span class=\"rt\">Frações (6º ano)</span><span class=\"tr\"><span class=\"br\" style=\"width:62%;background:#14467A\"></span></span><span class=\"vl\">62%</span></div><div class=\"ln\"><span class=\"rt\">Interpretação de gráficos (7º ano)</span><span class=\"tr\"><span class=\"br\" style=\"width:54%;background:#14467A\"></span></span><span class=\"vl\">54%</span></div><div class=\"ln\"><span class=\"rt\">Pontuação (6º ano)</span><span class=\"tr\"><span class=\"br\" style=\"width:47%;background:#14467A\"></span></span><span class=\"vl\">47%</span></div><div class=\"ln\"><span class=\"rt\">Equações do 1º grau (8º ano)</span><span class=\"tr\"><span class=\"br\" style=\"width:41%;background:#14467A\"></span></span><span class=\"vl\">41%</span></div><div class=\"ln\"><span class=\"rt\">Inferência em textos (9º ano)</span><span class=\"tr\"><span class=\"br\" style=\"width:33%;background:#14467A\"></span></span><span class=\"vl\">33%</span></div></div><figcaption>Gráfico (exemplo fictício). Percentual de alunos em Ainda não, por habilidade.</figcaption></figure><div class=\"caso\"><div class=\"tt\">Exemplo de uso · uma habilidade que trava a rede</div><p><b>Situação.</b> Frações aparece no topo das habilidades prioritárias do 6º ano em quase todas as escolas.</p><p><b>O que fazer.</b></p><ol><li>Verifique se a dificuldade vem de um pré-requisito do 5º ano.</li><li>Leve o tema ao encontro de formação dos professores de Matemática.</li><li>Em <b>Trilhas</b>, destaque na biblioteca as trilhas da habilidade.</li><li>Depois de um mês, abra novamente a tela e compare.</li></ol><p><b>Resultado esperado.</b> O percentual de alunos em Ainda não diminui. Se não mudar, reveja com os professores a abordagem em sala.</p></div>"},{"id":"c6","titulo":"Direção escolar: o seu menu","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>No menu</th><th>Para que serve</th><th>Quando usar</th></tr></thead><tbody><tr><td data-rotulo=\"No menu\">Visão geral</td><td data-rotulo=\"Para que serve\">Painel da escola: alunos matriculados e quantos têm responsável vinculado.</td><td data-rotulo=\"Quando usar\">Sempre que entrar.</td></tr><tr><td data-rotulo=\"No menu\">Aprendizagem</td><td data-rotulo=\"Para que serve\">Prática e habilidades recuperadas, turma a turma, em 7 ou 30 dias.</td><td data-rotulo=\"Quando usar\">Toda semana.</td></tr><tr><td data-rotulo=\"No menu\">Turmas e alunos</td><td data-rotulo=\"Para que serve\">Turmas, alunos e acessos dos alunos.</td><td data-rotulo=\"Quando usar\">Ao criar turma ou gerar novo acesso.</td></tr><tr><td data-rotulo=\"No menu\">Famílias</td><td data-rotulo=\"Para que serve\">Situação de acesso dos responsáveis, aluno por aluno.</td><td data-rotulo=\"Quando usar\">Todo mês.</td></tr><tr><td data-rotulo=\"No menu\">Atribuições</td><td data-rotulo=\"Para que serve\">Quadro de professores por componente e por turma.</td><td data-rotulo=\"Quando usar\">No início do ano e a cada mudança.</td></tr><tr><td data-rotulo=\"No menu\">Acesso das famílias</td><td data-rotulo=\"Para que serve\">Kit impresso individual ou convite digital para o responsável.</td><td data-rotulo=\"Quando usar\">Na matrícula e nas reuniões.</td></tr><tr><td data-rotulo=\"No menu\">Retorno das famílias</td><td data-rotulo=\"Para que serve\">O que os responsáveis disseram sobre os professores.</td><td data-rotulo=\"Quando usar\">Todo mês.</td></tr><tr><td data-rotulo=\"No menu\">Formação</td><td data-rotulo=\"Para que serve\">Este guia e os demais materiais de treinamento.</td><td data-rotulo=\"Quando usar\">Em caso de dúvida.</td></tr><tr><td data-rotulo=\"No menu\">Auditoria</td><td data-rotulo=\"Para que serve\">Registro das ações realizadas na escola.</td><td data-rotulo=\"Quando usar\">Quando precisar conferir quem fez o quê.</td></tr></tbody></table></div><figure><div class=\"tela\"><div class=\"barra\"><span></span><span></span><span></span><em>{{REDE}}</em></div><div class=\"app\"><aside><div class=\"logo\">{{REDE}}</div><div class=\"pf\">Direção escolar</div><div class=\"it at\">Visão geral</div><div class=\"it\">Aprendizagem</div><div class=\"it\">Turmas e alunos</div><div class=\"it\">Famílias</div><div class=\"it\">Atribuições</div><div class=\"it\">Acesso das famílias</div><div class=\"it\">Retorno das famílias</div><div class=\"it\">Formação</div><div class=\"it\">Auditoria</div></aside><main><div class=\"cab\"><b>Painel de gestão da escola</b></div><div class=\"corpo\"><div class=\"cards\"><div class=\"card\"><b>412</b><small>Alunos matriculados</small></div><div class=\"card\"><b>287</b><small>Com família vinculada</small></div><div class=\"card\"><b>14</b><small>Turmas</small></div></div><div style=\"height:2mm\"></div><div class=\"lst\"><div class=\"li\"><b>Turmas e alunos</b><small>Turmas, alunos, PINs e cartões</small></div><div class=\"li\"><b>Famílias</b><small>Responsáveis, convites e vínculos</small></div></div></div></main></div></div><figcaption>Ilustração da tela. O painel da direção resume a situação da escola.</figcaption></figure>"},{"id":"c7","titulo":"Organizar a escola no início do ano","html":"<ol class=\"passos\"><li>Confira em <b>Turmas e alunos</b> se todas as turmas e os alunos estão cadastrados. A Secretaria costuma importar por planilha.</li><li>Em <b>Atribuições</b>, ligue cada professor às suas turmas e componentes. Sem isso, o professor não vê as turmas.</li><li>Gere os acessos dos alunos e entregue na sala, pela agenda ou na matrícula.</li><li>Em <b>Acesso das famílias</b>, gere o kit de cada aluno ou envie o convite digital.</li><li>Combine com a coordenação a data do primeiro diagnóstico.</li></ol><div class=\"nota alerta\"><b>Aluno sem acesso não estuda</b><br/>O ponto que mais atrasa o início do reforço é a entrega dos acessos. Vale reservar um dia para isso em cada turma.</div>"},{"id":"c8","titulo":"Como trazer os responsáveis","html":"<p>O acesso dos responsáveis é oferecido pela escola. Quando o responsável acompanha, o aluno pratica mais.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Gerar</b><small>kit impresso ou convite digital</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Entregar</b><small>matrícula, reunião ou agenda</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Responsável entra</b><small>cria a conta pelo código</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Acompanha</b><small>vê a evolução do aluno</small></div></div><figcaption>Figura. Do kit de acesso ao acompanhamento.</figcaption></figure><figure><div class=\"colunas\"><div class=\"plot\"><div class=\"grp\"><div class=\"cols\"><span style=\"height:87.5%;background:#14467A\"><i>28</i></span><span style=\"height:75%;background:#1E8E5A\"><i>24</i></span></div><small>6º A</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:87.5%;background:#14467A\"><i>28</i></span><span style=\"height:46.875%;background:#1E8E5A\"><i>15</i></span></div><small>6º B</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:96.875%;background:#14467A\"><i>31</i></span><span style=\"height:84.375%;background:#1E8E5A\"><i>27</i></span></div><small>7º A</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:93.75%;background:#14467A\"><i>30</i></span><span style=\"height:34.375%;background:#1E8E5A\"><i>11</i></span></div><small>7º B</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:90.625%;background:#14467A\"><i>29</i></span><span style=\"height:68.75%;background:#1E8E5A\"><i>22</i></span></div><small>8º A</small></div></div><div class=\"leg\"><span><i style=\"background:#14467A\"></i>Alunos da turma</span><span><i style=\"background:#1E8E5A\"></i>Com responsável vinculado</span></div></div><figcaption>Gráfico (exemplo fictício). Adesão dos responsáveis por turma. O 6º B e o 7º B precisam de atenção.</figcaption></figure><div class=\"caso\"><div class=\"tt\">Exemplo de uso · turma com poucos responsáveis</div><p><b>Situação.</b> Na tela <b>Famílias</b>, o 7º B tem só 11 de 30 alunos com responsável vinculado.</p><p><b>O que fazer.</b></p><ol><li>Reimprima os kits dos alunos sem vínculo em <b>Acesso das famílias</b>.</li><li>Entregue na próxima reunião de responsáveis e mostre no celular como entrar.</li><li>Para quem não veio, envie pela agenda do aluno.</li><li>Acompanhe a tela <b>Famílias</b> nas semanas seguintes.</li></ol><p><b>Resultado esperado.</b> A adesão da turma sobe e, com ela, a prática dos alunos.</p></div><div class=\"nota\"><b>Um aluno, mais de um responsável</b><br/>Um aluno pode ter mais de um responsável vinculado, e um responsável pode acompanhar mais de um aluno.</div>"},{"id":"c9","titulo":"Como ler a aprendizagem da escola","html":"<p>A tela <b>Aprendizagem</b> mostra dois números por turma: quantos alunos praticaram e quantas habilidades foram recuperadas, nos últimos 7 ou 30 dias.</p><figure><div class=\"colunas\"><div class=\"plot\"><div class=\"grp\"><div class=\"cols\"><span style=\"height:82%;background:#14467A\"><i>82</i></span><span style=\"height:46%;background:#1E8E5A\"><i>46</i></span></div><small>6º A</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:39%;background:#14467A\"><i>39</i></span><span style=\"height:12%;background:#1E8E5A\"><i>12</i></span></div><small>6º B</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:75%;background:#14467A\"><i>75</i></span><span style=\"height:51%;background:#1E8E5A\"><i>51</i></span></div><small>7º A</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:71%;background:#14467A\"><i>71</i></span><span style=\"height:14.000000000000002%;background:#1E8E5A\"><i>14</i></span></div><small>7º B</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:64%;background:#14467A\"><i>64</i></span><span style=\"height:38%;background:#1E8E5A\"><i>38</i></span></div><small>8º A</small></div></div><div class=\"leg\"><span><i style=\"background:#14467A\"></i>Alunos que praticaram (%)</span><span><i style=\"background:#1E8E5A\"></i>Habilidades recuperadas</span></div></div><figcaption>Gráfico (exemplo fictício). Prática e recuperação por turma, em 30 dias.</figcaption></figure><h3>Ler os dois números juntos</h3><figure><div class=\"matriz\"><div class=\"ey\">Habilidades recuperadas</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Pouca prática, boa recuperação</b><small>Poucos alunos estudam, mas avançam. Ampliar o acesso.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Muita prática, boa recuperação</b><small>A turma está no caminho. Reconhecer e manter.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Pouca prática, pouca recuperação</b><small>Problema de acesso. Ver equipamentos e responsáveis. Exemplo: 6º B.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Muita prática, pouca recuperação</b><small>Conteúdo difícil para a turma. Ver pré-requisitos com o professor. Exemplo: 7º B.</small></div></div><div class=\"ex\">Prática dos alunos</div></div><figcaption>Figura. Como interpretar prática e recuperação em conjunto.</figcaption></figure>"},{"id":"c10","titulo":"Reunião pedagógica com dados","html":"<p>Um roteiro de 40 minutos para usar a plataforma na reunião com os professores.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Etapa</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Tempo\">5 min</td><td data-rotulo=\"Etapa\">Abertura</td><td data-rotulo=\"O que fazer\">Lembrar que os dados servem para apoiar, não para avaliar professores.</td></tr><tr><td data-rotulo=\"Tempo\">10 min</td><td data-rotulo=\"Etapa\">Visão da escola</td><td data-rotulo=\"O que fazer\">Mostrar prática e recuperação por turma, sem expor nomes de alunos.</td></tr><tr><td data-rotulo=\"Tempo\">10 min</td><td data-rotulo=\"Etapa\">Habilidades</td><td data-rotulo=\"O que fazer\">Apresentar as três habilidades com mais alunos em Ainda não.</td></tr><tr><td data-rotulo=\"Tempo\">10 min</td><td data-rotulo=\"Etapa\">Combinados</td><td data-rotulo=\"O que fazer\">Cada professor define uma retomada para a semana.</td></tr><tr><td data-rotulo=\"Tempo\">5 min</td><td data-rotulo=\"Etapa\">Fechamento</td><td data-rotulo=\"O que fazer\">Marcar a data para conferir o que mudou.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Cuidado com comparações</b><br/>Turmas têm pontos de partida diferentes. Compare cada turma com ela mesma ao longo do tempo, não uma turma com outra.</div>"},{"id":"c11","titulo":"Rotina de acompanhamento","html":"<figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Olhar</b><small>Ver a prática e as habilidades prioritárias.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Escolher</b><small>Definir a turma e a habilidade que precisam de apoio.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Agir</b><small>Conversar com o professor e com os responsáveis.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Conferir</b><small>Ver, na semana seguinte, o que mudou.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo de acompanhamento da gestão.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quando</th><th>Coordenação pedagógica</th><th>Direção escolar</th></tr></thead><tbody><tr><td data-rotulo=\"Quando\">Toda semana</td><td data-rotulo=\"Coordenação pedagógica\">Ver as habilidades prioritárias e as escolas com pouca participação.</td><td data-rotulo=\"Direção escolar\">Ver em Aprendizagem as turmas que não praticaram.</td></tr><tr><td data-rotulo=\"Quando\">Todo mês</td><td data-rotulo=\"Coordenação pedagógica\">Revisar as trilhas pendentes de aprovação e ler o retorno das famílias.</td><td data-rotulo=\"Direção escolar\">Conferir em Famílias os responsáveis sem acesso e reenviar convites.</td></tr><tr><td data-rotulo=\"Quando\">A cada bimestre</td><td data-rotulo=\"Coordenação pedagógica\">Abrir novo diagnóstico para medir a evolução.</td><td data-rotulo=\"Direção escolar\">Revisar o quadro de atribuições e as turmas.</td></tr></tbody></table></div>"},{"id":"c12","titulo":"Ética no uso da plataforma","html":"<p>A plataforma trata de crianças e adolescentes e usa inteligência artificial. Por isso, o uso ético faz parte do trabalho de quem tem acesso de equipe. Os princípios abaixo valem para todos os perfis.</p><div class=\"tb\"><table><thead><tr><th>Princípio</th><th>O que significa na prática</th></tr></thead><tbody><tr><td data-rotulo=\"Princípio\">Melhor interesse do aluno</td><td data-rotulo=\"O que significa na prática\">Toda informação é usada para ajudar o aluno a aprender. Não para punir, expor ou comparar.</td></tr><tr><td data-rotulo=\"Princípio\">Decisão humana</td><td data-rotulo=\"O que significa na prática\">A inteligência artificial apoia o estudo. As decisões pedagógicas sobre o aluno são sempre de pessoas.</td></tr><tr><td data-rotulo=\"Princípio\">Transparência</td><td data-rotulo=\"O que significa na prática\">Aluno e responsáveis sabem que a plataforma existe, para que serve e o que ela mostra.</td></tr><tr><td data-rotulo=\"Princípio\">Equidade</td><td data-rotulo=\"O que significa na prática\">Quem não tem equipamento ou internet em casa não pode ser prejudicado. A escola busca alternativas de acesso.</td></tr><tr><td data-rotulo=\"Princípio\">Sigilo</td><td data-rotulo=\"O que significa na prática\">Dados de um aluno só são vistos por quem precisa deles para o trabalho.</td></tr><tr><td data-rotulo=\"Princípio\">Honestidade dos dados</td><td data-rotulo=\"O que significa na prática\">Ninguém responde pelo aluno nem altera cadastro para melhorar indicadores.</td></tr></tbody></table></div><h3>O que fazer e o que não fazer</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td data-rotulo=\"Faça\">Usar os indicadores para apoiar turmas e professores.</td><td data-rotulo=\"Não faça\">Usar os indicadores para punir ou classificar professores.</td></tr><tr><td data-rotulo=\"Faça\">Comparar cada turma com ela mesma ao longo do tempo.</td><td data-rotulo=\"Não faça\">Publicar ranking de turmas, professores ou alunos.</td></tr><tr><td data-rotulo=\"Faça\">Tratar o retorno das famílias com reserva e ouvir o professor.</td><td data-rotulo=\"Não faça\">Divulgar o retorno de um responsável sobre um professor.</td></tr><tr><td data-rotulo=\"Faça\">Buscar alternativa de acesso para quem não tem equipamento.</td><td data-rotulo=\"Não faça\">Cobrar metas de prática de turmas sem condição de acesso.</td></tr><tr><td data-rotulo=\"Faça\">Manter os cadastros fiéis à realidade.</td><td data-rotulo=\"Não faça\">Alterar cadastro ou pedir que respondam pelo aluno para melhorar indicadores.</td></tr></tbody></table></div><h3>Inteligência artificial: o que ela faz e o que não faz</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A inteligência artificial</th><th>Situação</th></tr></thead><tbody><tr><td data-rotulo=\"A inteligência artificial\">Orienta o raciocínio do aluno com perguntas e dicas</td><td data-rotulo=\"Situação\">Faz</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Dá retorno sobre o texto do aluno, parágrafo por parágrafo</td><td data-rotulo=\"Situação\">Faz</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Entrega a resposta pronta ou reescreve o texto do aluno</td><td data-rotulo=\"Situação\">Não faz</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Recebe o nome ou a matrícula do aluno</td><td data-rotulo=\"Situação\">Não recebe</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Decide nota, aprovação ou encaminhamento do aluno</td><td data-rotulo=\"Situação\">Não decide</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Se algo parecer errado</b><br/>Uma dica inadequada, um conteúdo com erro ou um comportamento estranho da plataforma devem ser comunicados à direção ou à Secretaria. O registro ajuda a corrigir para toda a rede.</div>"},{"id":"c13","titulo":"Proteção de dados","html":"<p>A Lei Geral de Proteção de Dados (Lei nº 13.709/2018) dá proteção reforçada aos dados de crianças e adolescentes. O Município é o responsável pelos dados da rede, e cada servidor responde pelo uso que faz do seu acesso.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dado</th><th>Quem vê</th><th>Cuidado</th></tr></thead><tbody><tr><td data-rotulo=\"Dado\">Nome, turma e evolução do aluno</td><td data-rotulo=\"Quem vê\">Professores da turma, direção, coordenação e Secretaria</td><td data-rotulo=\"Cuidado\">Usar só para fins pedagógicos e de gestão.</td></tr><tr><td data-rotulo=\"Dado\">Contato dos responsáveis</td><td data-rotulo=\"Quem vê\">Direção e Secretaria</td><td data-rotulo=\"Cuidado\">Não repassar a terceiros nem usar para outros assuntos.</td></tr><tr><td data-rotulo=\"Dado\">Respostas e textos do aluno</td><td data-rotulo=\"Quem vê\">Professores da turma</td><td data-rotulo=\"Cuidado\">Não divulgar, mesmo como bom exemplo, sem autorização.</td></tr><tr><td data-rotulo=\"Dado\">Seu usuário e senha</td><td data-rotulo=\"Quem vê\">Só você</td><td data-rotulo=\"Cuidado\">Não emprestar. Sair da conta em computador compartilhado.</td></tr></tbody></table></div><ul><li>Não publique telas com nome de aluno em redes sociais ou grupos de mensagens.</li><li>Para mostrar a plataforma em reuniões abertas, use dados de exemplo ou oculte os nomes.</li><li>Os dados dos alunos não são usados para publicidade nem cedidos a terceiros.</li><li>Quando um servidor deixa a escola, a direção ou a Secretaria desativa o acesso dele.</li></ul><div class=\"nota alerta\"><b>Incidente com dados</b><br/>Acesso indevido, senha compartilhada, tela exposta ou dado enviado à pessoa errada devem ser comunicados no mesmo dia à direção, que avisa a Secretaria. A Secretaria tem um encarregado de dados para tratar o caso.</div>"},{"id":"c14","titulo":"Situações e soluções","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Uma turma não pratica.</td><td data-rotulo=\"O que fazer\">Conversar com o professor, conferir se os alunos têm acesso e se os responsáveis entraram.</td></tr><tr><td data-rotulo=\"Situação\">Uma habilidade trava a turma inteira.</td><td data-rotulo=\"O que fazer\">Levar ao planejamento do professor. Pode faltar um pré-requisito de ano anterior.</td></tr><tr><td data-rotulo=\"Situação\">O professor não vê as turmas.</td><td data-rotulo=\"O que fazer\">Fazer o vínculo no quadro de Atribuições.</td></tr><tr><td data-rotulo=\"Situação\">O aluno esqueceu como entrar.</td><td data-rotulo=\"O que fazer\">Gerar um novo acesso em Turmas e alunos.</td></tr><tr><td data-rotulo=\"Situação\">O responsável perdeu o acesso.</td><td data-rotulo=\"O que fazer\">Reenviar o convite ou reimprimir o kit em Acesso das famílias.</td></tr><tr><td data-rotulo=\"Situação\">Um aluno mudou de turma.</td><td data-rotulo=\"O que fazer\">Atualizar em Turmas e alunos ou pedir a atualização à Secretaria.</td></tr><tr><td data-rotulo=\"Situação\">Um servidor saiu da escola.</td><td data-rotulo=\"O que fazer\">Pedir à Secretaria a desativação do acesso.</td></tr><tr><td data-rotulo=\"Situação\">Há trilhas aguardando aprovação.</td><td data-rotulo=\"O que fazer\">A coordenação analisa em Trilhas e aprova ou devolve com orientação.</td></tr></tbody></table></div>"},{"id":"c15","titulo":"As seis primeiras semanas","html":"<p>A implantação na escola se decide nas primeiras semanas. Quando os acessos chegam aos alunos com orientação, e os professores sabem o que fazer com o mapa, o uso se mantém. Quando os acessos são apenas entregues, o uso cai depois da novidade.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Semana</th><th>Direção</th><th>Coordenação pedagógica</th></tr></thead><tbody><tr><td data-rotulo=\"Semana\">1</td><td data-rotulo=\"Direção\">Conferir turmas, alunos e atribuição dos professores. Definir quem cuida dos acessos.</td><td data-rotulo=\"Coordenação pedagógica\">Estudar o guia e o caminho do aluno. Preparar a oficina com os professores.</td></tr><tr><td data-rotulo=\"Semana\">2</td><td data-rotulo=\"Direção\">Organizar horários e espaços de uso. Conferir equipamentos e conexão.</td><td data-rotulo=\"Coordenação pedagógica\">Oficina com os professores: como o aluno estuda e como ler o mapa.</td></tr><tr><td data-rotulo=\"Semana\">3</td><td data-rotulo=\"Direção\">Entregar os acessos aos alunos, turma por turma, com explicação.</td><td data-rotulo=\"Coordenação pedagógica\">Acompanhar a primeira sessão de cada turma.</td></tr><tr><td data-rotulo=\"Semana\">4</td><td data-rotulo=\"Direção\">Reunião com os responsáveis e entrega dos códigos de acesso.</td><td data-rotulo=\"Coordenação pedagógica\">Abrir o primeiro diagnóstico, se a rede assim definir. Ver quem ainda não entrou.</td></tr><tr><td data-rotulo=\"Semana\">5</td><td data-rotulo=\"Direção\">Ver a prática por turma. Procurar as turmas com pouco uso.</td><td data-rotulo=\"Coordenação pedagógica\">Primeira leitura do mapa com os professores, por ano ou área.</td></tr><tr><td data-rotulo=\"Semana\">6</td><td data-rotulo=\"Direção\">Balanço com a equipe. Ajustar horários.</td><td data-rotulo=\"Coordenação pedagógica\">Escolher com os professores as habilidades prioritárias de cada turma.</td></tr></tbody></table></div><h3>O que precisa estar pronto antes da entrega dos acessos</h3><ul class=\"chk\"><li><span></span>Todos os alunos estão nas turmas corretas.</li><li><span></span>Cada professor vê as suas turmas.</li><li><span></span>Há horário reservado para cada turma usar o reforço na escola.</li><li><span></span>Os equipamentos foram testados com a conexão da escola.</li><li><span></span>Um servidor sabe gerar novo acesso para quem esquecer.</li><li><span></span>Os professores conhecem a tela do aluno.</li><li><span></span>A data da reunião com os responsáveis está marcada.</li></ul><div class=\"nota\"><b>A primeira sessão é acompanhada</b><br/>Na primeira vez, cada turma entra junto, com o professor e um apoio da gestão. Os problemas de acesso se resolvem na hora, e o aluno sai sabendo o que fazer em casa.</div>"},{"id":"c16","titulo":"Horários, espaços e equipamentos","html":"<p>O reforço na escola depende de três coisas simples: saber quando cada turma usa, onde usa e com que equipamentos. Uma grade afixada na sala dos professores evita disputas e garante que nenhuma turma fique de fora.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Horário</th><th>Segunda</th><th>Terça</th><th>Quarta</th><th>Quinta</th><th>Sexta</th></tr></thead><tbody><tr><td data-rotulo=\"Horário\">1ª aula</td><td data-rotulo=\"Segunda\">6º A</td><td data-rotulo=\"Terça\">7º A</td><td data-rotulo=\"Quarta\">8º A</td><td data-rotulo=\"Quinta\">9º A</td><td data-rotulo=\"Sexta\">Reserva</td></tr><tr><td data-rotulo=\"Horário\">2ª aula</td><td data-rotulo=\"Segunda\">6º B</td><td data-rotulo=\"Terça\">7º B</td><td data-rotulo=\"Quarta\">8º B</td><td data-rotulo=\"Quinta\">9º B</td><td data-rotulo=\"Sexta\">Reserva</td></tr><tr><td data-rotulo=\"Horário\">3ª aula</td><td data-rotulo=\"Segunda\">3º A</td><td data-rotulo=\"Terça\">4º A</td><td data-rotulo=\"Quarta\">5º A</td><td data-rotulo=\"Quinta\">3º B</td><td data-rotulo=\"Sexta\">4º B</td></tr><tr><td data-rotulo=\"Horário\">4ª aula</td><td data-rotulo=\"Segunda\">5º B</td><td data-rotulo=\"Terça\">Alunos sem acesso em casa</td><td data-rotulo=\"Quarta\">Alunos sem acesso em casa</td><td data-rotulo=\"Quinta\">Alunos sem acesso em casa</td><td data-rotulo=\"Sexta\">Manutenção</td></tr></tbody></table></div><p>O quadro acima é um exemplo de grade semanal para um conjunto de equipamentos. Os horários de reserva cobrem feriados e imprevistos.</p><h3>Cuidados com os equipamentos</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Rotina</th><th>Quem</th><th>Quando</th></tr></thead><tbody><tr><td data-rotulo=\"Rotina\">Carregar os equipamentos</td><td data-rotulo=\"Quem\">Servidor designado</td><td data-rotulo=\"Quando\">Ao fim de cada turno</td></tr><tr><td data-rotulo=\"Rotina\">Conferir a quantidade na entrega e na devolução</td><td data-rotulo=\"Quem\">Professor da aula</td><td data-rotulo=\"Quando\">A cada uso</td></tr><tr><td data-rotulo=\"Rotina\">Guardar em local trancado e arejado</td><td data-rotulo=\"Quem\">Servidor designado</td><td data-rotulo=\"Quando\">Diariamente</td></tr><tr><td data-rotulo=\"Rotina\">Registrar equipamento com defeito</td><td data-rotulo=\"Quem\">Professor e servidor designado</td><td data-rotulo=\"Quando\">No mesmo dia</td></tr><tr><td data-rotulo=\"Rotina\">Comunicar perda, furto ou dano</td><td data-rotulo=\"Quem\">Direção</td><td data-rotulo=\"Quando\">No mesmo dia</td></tr><tr><td data-rotulo=\"Rotina\">Limpar as telas</td><td data-rotulo=\"Quem\">Servidor designado</td><td data-rotulo=\"Quando\">Semanalmente</td></tr><tr><td data-rotulo=\"Rotina\">Conferir o inventário</td><td data-rotulo=\"Quem\">Direção</td><td data-rotulo=\"Quando\">Mensalmente</td></tr></tbody></table></div><h3>Procedimento de sala para o uso</h3><ol class=\"passos\"><li>Dois alunos distribuem os equipamentos, por número.</li><li>Cada aluno entra com o próprio acesso.</li><li>O professor escreve no quadro o objetivo e o tempo.</li><li>Cinco minutos antes do fim, os alunos saem das contas.</li><li>Os mesmos dois alunos recolhem, e o professor confere a quantidade.</li></ol><div class=\"nota alerta\"><b>Cada aluno, o seu acesso</b><br/>Entrar com o acesso de um colega mistura as trilhas dos dois e torna os dados inúteis. Quem esqueceu pede novo acesso à direção.</div>"},{"id":"c17","titulo":"Acessos: situações do dia a dia","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Aluno esqueceu como entrar</td><td data-rotulo=\"O que fazer\">Gerar novo acesso em Turmas e alunos e entregar ao aluno.</td></tr><tr><td data-rotulo=\"Situação\">Aluno novo na escola</td><td data-rotulo=\"O que fazer\">Incluir na turma e entregar o acesso com uma explicação individual.</td></tr><tr><td data-rotulo=\"Situação\">Aluno mudou de turma</td><td data-rotulo=\"O que fazer\">Atualizar a turma. O histórico do aluno o acompanha.</td></tr><tr><td data-rotulo=\"Situação\">Aluno transferido para outra escola da rede</td><td data-rotulo=\"O que fazer\">Registrar a transferência conforme a orientação da Secretaria.</td></tr><tr><td data-rotulo=\"Situação\">Aluno saiu da rede</td><td data-rotulo=\"O que fazer\">Registrar a saída. Não reaproveitar o acesso.</td></tr><tr><td data-rotulo=\"Situação\">Responsável perdeu o código</td><td data-rotulo=\"O que fazer\">Gerar novo código em Acesso das famílias.</td></tr><tr><td data-rotulo=\"Situação\">Responsável quer acompanhar dois filhos</td><td data-rotulo=\"O que fazer\">Usar o código de cada aluno na mesma conta.</td></tr><tr><td data-rotulo=\"Situação\">Dois responsáveis querem acompanhar</td><td data-rotulo=\"O que fazer\">Cada um cria a própria conta e usa o código do aluno.</td></tr><tr><td data-rotulo=\"Situação\">Professor não vê uma turma</td><td data-rotulo=\"O que fazer\">Conferir a atribuição do professor.</td></tr><tr><td data-rotulo=\"Situação\">Professor deixou a escola</td><td data-rotulo=\"O que fazer\">Retirar as atribuições e comunicar à Secretaria para desativar o acesso.</td></tr><tr><td data-rotulo=\"Situação\">Suspeita de uso do acesso por outra pessoa</td><td data-rotulo=\"O que fazer\">Gerar novo acesso e orientar o aluno e a família.</td></tr></tbody></table></div><h3>Entrega dos acessos aos alunos</h3><ul><li>A entrega é individual, em mão, e não em lista afixada.</li><li>O aluno é orientado a não emprestar o acesso.</li><li>Os menores levam o acesso colado na agenda, em comum acordo com a família.</li><li>A escola não mantém planilhas com acessos em computadores compartilhados nem em grupos de mensagens.</li><li>A folha de acesso que sobrar é guardada pela direção.</li></ul><div class=\"nota\"><b>Registro das ações</b><br/>As ações de gestão ficam registradas na plataforma, em Auditoria. O registro protege a escola e permite esclarecer dúvidas.</div>"},{"id":"c18","titulo":"Como engajar os professores","html":"<p>A maioria dos professores adere quando percebe que o reforço poupa trabalho e mostra algo que ele não via. As resistências costumam ter motivo, e vale ouvi-las.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O que o professor diz</th><th>O que pode estar por trás</th><th>Como responder</th></tr></thead><tbody><tr><td data-rotulo=\"O que o professor diz\">\"É mais uma coisa para fazer.\"</td><td data-rotulo=\"O que pode estar por trás\">Sobrecarga real.</td><td data-rotulo=\"Como responder\">Mostrar que ele não aplica nem corrige nada. Pedir só meia hora por semana para ler o mapa.</td></tr><tr><td data-rotulo=\"O que o professor diz\">\"Não tenho tempo de dar o conteúdo, imagine reforço.\"</td><td data-rotulo=\"O que pode estar por trás\">Pressão pelo currículo do ano.</td><td data-rotulo=\"Como responder\">Mostrar que sem a base o conteúdo do ano não avança. Começar por uma habilidade.</td></tr><tr><td data-rotulo=\"O que o professor diz\">\"Os alunos não têm internet.\"</td><td data-rotulo=\"O que pode estar por trás\">Preocupação legítima com a equidade.</td><td data-rotulo=\"Como responder\">Apresentar a grade de uso na escola e os horários para quem não tem acesso.</td></tr><tr><td data-rotulo=\"O que o professor diz\">\"A máquina vai me substituir.\"</td><td data-rotulo=\"O que pode estar por trás\">Insegurança.</td><td data-rotulo=\"Como responder\">Explicar que as decisões pedagógicas são do professor e que o tutor não dá resposta nem nota.</td></tr><tr><td data-rotulo=\"O que o professor diz\">\"Esse dado não reflete a minha turma.\"</td><td data-rotulo=\"O que pode estar por trás\">Desconfiança do diagnóstico.</td><td data-rotulo=\"Como responder\">Analisar juntos atividades da turma e comparar com o mapa.</td></tr><tr><td data-rotulo=\"O que o professor diz\">\"Não sei mexer.\"</td><td data-rotulo=\"O que pode estar por trás\">Pouca familiaridade com tecnologia.</td><td data-rotulo=\"Como responder\">Sentar ao lado, fazer junto e indicar um colega de apoio.</td></tr><tr><td data-rotulo=\"O que o professor diz\">\"Já tentaram outras coisas e não deu em nada.\"</td><td data-rotulo=\"O que pode estar por trás\">Cansaço de projetos que passam.</td><td data-rotulo=\"Como responder\">Mostrar resultados da própria escola em poucas semanas.</td></tr></tbody></table></div><h3>O que funciona</h3><ul><li>Começar com os professores que se interessam e pedir que mostrem aos colegas.</li><li>Trazer para a reunião o mapa de uma turma real e planejar uma aula a partir dele.</li><li>Reconhecer em público quem usou o mapa para mudar a aula.</li><li>Pedir pouco e com constância.</li><li>Resolver depressa os problemas práticos: acesso, equipamento, horário.</li><li>Nunca usar os dados de uma turma para constranger o professor.</li></ul><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · devolutiva com dados</div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Vi que o 7º B praticou bastante neste mês. Parabéns pelo trabalho com a turma.</div></div><div class=\"f o\"><div class=\"q\">Professor</div><div class=\"b\">Eles gostam. Mas não vejo avanço em equações.</div></div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Reparei nisso. O mapa mostra muitos alunos em Ainda não em operações com números negativos. Pode ser a base que falta.</div></div><div class=\"f o\"><div class=\"q\">Professor</div><div class=\"b\">Faz sentido. Eles erram o sinal o tempo todo.</div></div><div class=\"f\"><div class=\"q\">Coordenação</div><div class=\"b\">Que tal uma aula de retomada na semana que vem? Posso ajudar a preparar o material.</div></div></div>"},{"id":"c19","titulo":"Do dado à decisão","html":"<p>Os números da plataforma só ajudam quando viram decisão. A rotina abaixo leva do indicador à ação em quatro passos.</p><figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Olhar</b><small>Prática e recuperação, por turma.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Perguntar</b><small>O que explica este número?</small></div><div class=\"q\"><span class=\"n\">3</span><b>Decidir</b><small>Uma ação, com responsável e prazo.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Voltar</b><small>Conferir o indicador depois de duas a quatro semanas.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo de uso dos dados pela gestão.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O que os dados mostram</th><th>Perguntas a fazer</th><th>Decisões possíveis</th></tr></thead><tbody><tr><td data-rotulo=\"O que os dados mostram\">Uma turma com pouca prática</td><td data-rotulo=\"Perguntas a fazer\">Os alunos têm acesso? A turma tem horário na escola? O professor conhece o mapa?</td><td data-rotulo=\"Decisões possíveis\">Rever a grade. Regenerar acessos. Apoiar o professor.</td></tr><tr><td data-rotulo=\"O que os dados mostram\">Uma turma com muita prática e pouca recuperação</td><td data-rotulo=\"Perguntas a fazer\">Qual habilidade trava? Há pré-requisito em falta?</td><td data-rotulo=\"Decisões possíveis\">Aula de retomada da base. Grupos por nível.</td></tr><tr><td data-rotulo=\"O que os dados mostram\">Uma habilidade prioritária em vários anos</td><td data-rotulo=\"Perguntas a fazer\">O problema começa em que ano?</td><td data-rotulo=\"Decisões possíveis\">Formação dos professores no tema. Ação desde os anos iniciais.</td></tr><tr><td data-rotulo=\"O que os dados mostram\">Poucos responsáveis com conta</td><td data-rotulo=\"Perguntas a fazer\">Os códigos foram entregues? Houve reunião?</td><td data-rotulo=\"Decisões possíveis\">Nova entrega, com ajuda para o cadastro.</td></tr><tr><td data-rotulo=\"O que os dados mostram\">Queda de prática depois de um feriado ou recesso</td><td data-rotulo=\"Perguntas a fazer\">A rotina foi retomada?</td><td data-rotulo=\"Decisões possíveis\">Relançar com as turmas e avisar as famílias.</td></tr><tr><td data-rotulo=\"O que os dados mostram\">Alunos sem nenhuma atividade</td><td data-rotulo=\"Perguntas a fazer\">Estão frequentando? Têm acesso?</td><td data-rotulo=\"Decisões possíveis\">Busca ativa e horário na escola.</td></tr></tbody></table></div><h3>Metas da escola para o reforço</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Meta</th><th>Como acompanhar</th><th>Cuidado</th></tr></thead><tbody><tr><td data-rotulo=\"Meta\">Proporção de alunos que praticam toda semana</td><td data-rotulo=\"Como acompanhar\">Indicador de prática, por turma.</td><td data-rotulo=\"Cuidado\">Só cobrar de turmas com condição de acesso garantida.</td></tr><tr><td data-rotulo=\"Meta\">Habilidades recuperadas por turma</td><td data-rotulo=\"Como acompanhar\">Indicador de recuperação.</td><td data-rotulo=\"Cuidado\">Comparar a turma com ela mesma.</td></tr><tr><td data-rotulo=\"Meta\">Responsáveis com conta ativa</td><td data-rotulo=\"Como acompanhar\">Tela Famílias.</td><td data-rotulo=\"Cuidado\">Oferecer ajuda a quem tem dificuldade com o celular.</td></tr><tr><td data-rotulo=\"Meta\">Professores que consultam o mapa</td><td data-rotulo=\"Como acompanhar\">Conversa nas reuniões.</td><td data-rotulo=\"Cuidado\">Apoiar antes de cobrar.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Meta não é para maquiar</b><br/>Quando a meta vira pressão, aparecem atalhos: responder pelo aluno, entrar só para constar. Deixe claro à equipe que o objetivo é o aluno aprender, e que número baixo com explicação honesta vale mais do que número alto sem aprendizagem.</div>"},{"id":"c20","titulo":"Habilidades prioritárias e formação","html":"<p>A tela de habilidades prioritárias mostra onde a escola ou a rede concentra mais alunos em Ainda não. Ela é o melhor ponto de partida para a pauta de formação.</p><ol class=\"passos\"><li>Abra as habilidades prioritárias por ano e componente.</li><li>Escolha as três primeiras de cada ano.</li><li>Verifique se elas se repetem em anos seguidos: isso indica uma lacuna que se acumula.</li><li>Leve à reunião pedagógica e pergunte aos professores o que observam em sala.</li><li>Escolha uma habilidade para ser o tema da formação do bimestre.</li><li>Planeje com os professores uma sequência de aulas de retomada.</li><li>Depois de um mês, volte à tela e veja o que mudou.</li></ol><figure><div class=\"barras\"><div class=\"ln\"><span class=\"rt\">Interpretar enunciados</span><span class=\"tr\"><span class=\"br\" style=\"width:62%;background:#C44536\"></span></span><span class=\"vl\">62%</span></div><div class=\"ln\"><span class=\"rt\">Operações com frações</span><span class=\"tr\"><span class=\"br\" style=\"width:55.00000000000001%;background:#C44536\"></span></span><span class=\"vl\">55%</span></div><div class=\"ln\"><span class=\"rt\">Inferir informações</span><span class=\"tr\"><span class=\"br\" style=\"width:48%;background:#D9920B\"></span></span><span class=\"vl\">48%</span></div><div class=\"ln\"><span class=\"rt\">Leitura de gráficos</span><span class=\"tr\"><span class=\"br\" style=\"width:31%;background:#D9920B\"></span></span><span class=\"vl\">31%</span></div></div><figcaption>Gráfico (exemplo fictício). Proporção de alunos em Ainda não nas habilidades prioritárias do 6º ano.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Se a habilidade prioritária é</th><th>A formação pode tratar de</th></tr></thead><tbody><tr><td data-rotulo=\"Se a habilidade prioritária é\">De leitura, em vários componentes</td><td data-rotulo=\"A formação pode tratar de\">Estratégias de leitura em todas as disciplinas.</td></tr><tr><td data-rotulo=\"Se a habilidade prioritária é\">De base matemática</td><td data-rotulo=\"A formação pode tratar de\">Uso de material concreto e resolução de problemas.</td></tr><tr><td data-rotulo=\"Se a habilidade prioritária é\">De escrita</td><td data-rotulo=\"A formação pode tratar de\">Planejamento e revisão de textos, com as redações guiadas.</td></tr><tr><td data-rotulo=\"Se a habilidade prioritária é\">Diferente em cada turma</td><td data-rotulo=\"A formação pode tratar de\">Leitura do mapa e planejamento da retomada por turma.</td></tr></tbody></table></div><div class=\"nota\"><b>Uma prioridade da escola inteira</b><br/>Quando a mesma habilidade aparece em vários anos, vale um compromisso de toda a equipe. Leitura de enunciados, por exemplo, pode ser trabalhada por todos os professores, cada um na sua disciplina.</div>"},{"id":"c21","titulo":"O conselho de classe com os dados do reforço","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento do conselho</th><th>Como os dados entram</th></tr></thead><tbody><tr><td data-rotulo=\"Momento do conselho\">Preparação</td><td data-rotulo=\"Como os dados entram\">A coordenação leva, por turma, a prática, as habilidades recuperadas e as prioritárias.</td></tr><tr><td data-rotulo=\"Momento do conselho\">Olhar a turma</td><td data-rotulo=\"Como os dados entram\">O que a turma recuperou no bimestre? O que continua em Ainda não?</td></tr><tr><td data-rotulo=\"Momento do conselho\">Olhar os alunos</td><td data-rotulo=\"Como os dados entram\">Quem avançou e merece reconhecimento? Quem não praticou e por quê?</td></tr><tr><td data-rotulo=\"Momento do conselho\">Decidir</td><td data-rotulo=\"Como os dados entram\">Que habilidade será retomada por todos os professores da turma? Quem fala com quais famílias?</td></tr><tr><td data-rotulo=\"Momento do conselho\">Registrar</td><td data-rotulo=\"Como os dados entram\">Encaminhamentos com responsável e prazo.</td></tr></tbody></table></div><h3>O que os dados não decidem</h3><ul><li>Aprovação ou reprovação.</li><li>Nota ou conceito.</li><li>Encaminhamento para avaliação de saúde, que depende da observação do professor e da conversa com a família.</li><li>Julgamento sobre o trabalho do professor.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Fala comum no conselho</th><th>Como os dados ajudam a reformular</th></tr></thead><tbody><tr><td data-rotulo=\"Fala comum no conselho\">\"Essa turma não aprende.\"</td><td data-rotulo=\"Como os dados ajudam a reformular\">\"Esta turma recuperou cinco habilidades e continua em Ainda não em duas. Vamos olhar essas duas.\"</td></tr><tr><td data-rotulo=\"Fala comum no conselho\">\"Ele não faz nada.\"</td><td data-rotulo=\"Como os dados ajudam a reformular\">\"Ele não entrou no reforço neste mês. Tem acesso em casa? Está frequentando?\"</td></tr><tr><td data-rotulo=\"Fala comum no conselho\">\"A família não acompanha.\"</td><td data-rotulo=\"Como os dados ajudam a reformular\">\"O responsável ainda não criou a conta. Vamos entregar o código de novo e oferecer ajuda.\"</td></tr></tbody></table></div><div class=\"nota\"><b>Dados por turma, nomes com reserva</b><br/>Na projeção, mostre os dados por turma. Os nomes dos alunos aparecem apenas na discussão de cada caso, entre os professores daquele aluno.</div>"},{"id":"c22","titulo":"Plano de comunicação com as famílias","html":"<p>A participação das famílias não se resolve com um único comunicado. Um plano simples, ao longo do ano, mantém os responsáveis por perto.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quando</th><th>Ação</th><th>Objetivo</th></tr></thead><tbody><tr><td data-rotulo=\"Quando\">Início do ano</td><td data-rotulo=\"Ação\">Reunião de apresentação e entrega dos códigos.</td><td data-rotulo=\"Objetivo\">Todos entendem o que é o reforço e criam a conta.</td></tr><tr><td data-rotulo=\"Quando\">Duas semanas depois</td><td data-rotulo=\"Ação\">Novo contato com quem não criou a conta.</td><td data-rotulo=\"Objetivo\">Ajudar quem teve dificuldade.</td></tr><tr><td data-rotulo=\"Quando\">Todo mês</td><td data-rotulo=\"Ação\">Mensagem curta com uma orientação: horário de estudo, lugar calmo, como ajudar sem responder.</td><td data-rotulo=\"Objetivo\">Manter o hábito.</td></tr><tr><td data-rotulo=\"Quando\">Todo bimestre</td><td data-rotulo=\"Ação\">Reunião com os responsáveis, com o avanço geral das turmas.</td><td data-rotulo=\"Objetivo\">Mostrar resultado e ouvir.</td></tr><tr><td data-rotulo=\"Quando\">Quando o professor indicar</td><td data-rotulo=\"Ação\">Aviso individual de reforço em uma matéria.</td><td data-rotulo=\"Objetivo\">Orientar o estudo.</td></tr><tr><td data-rotulo=\"Quando\">Fim do ano</td><td data-rotulo=\"Ação\">Balanço e agradecimento.</td><td data-rotulo=\"Objetivo\">Reconhecer o esforço das famílias.</td></tr></tbody></table></div><h3>Quem ainda não entrou</h3><ol class=\"passos\"><li>Ver na tela Famílias quais responsáveis não criaram a conta.</li><li>Entregar novamente o código, pela agenda ou em mão.</li><li>Oferecer um horário na escola para fazer o cadastro com ajuda.</li><li>Perguntar se há dificuldade com aparelho, internet ou leitura.</li><li>Registrar quem precisa de outro tipo de acompanhamento, como bilhetes e conversas presenciais.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Dificuldade da família</th><th>O que a escola pode fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Dificuldade da família\">Não tem celular com internet</td><td data-rotulo=\"O que a escola pode fazer\">Informar a evolução em reuniões e por bilhete.</td></tr><tr><td data-rotulo=\"Dificuldade da família\">Tem dificuldade para ler</td><td data-rotulo=\"O que a escola pode fazer\">Explicar pessoalmente, com a tela na frente.</td></tr><tr><td data-rotulo=\"Dificuldade da família\">Trabalha no horário das reuniões</td><td data-rotulo=\"O que a escola pode fazer\">Oferecer outro horário ou conversa por telefone.</td></tr><tr><td data-rotulo=\"Dificuldade da família\">Desconfia da tecnologia</td><td data-rotulo=\"O que a escola pode fazer\">Mostrar o que a plataforma faz e o que não faz, e como os dados são protegidos.</td></tr><tr><td data-rotulo=\"Dificuldade da família\">Responde pelo aluno</td><td data-rotulo=\"O que a escola pode fazer\">Explicar, com respeito, por que isso atrapalha.</td></tr></tbody></table></div><div class=\"nota\"><b>O retorno das famílias</b><br/>As observações enviadas pelos responsáveis chegam à tela de retorno das famílias. Ler e responder mostra que a escola ouve.</div>"},{"id":"c23","titulo":"Equidade: ninguém fica para trás","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Grupo</th><th>Risco</th><th>Medida da escola</th></tr></thead><tbody><tr><td data-rotulo=\"Grupo\">Alunos sem aparelho ou internet em casa</td><td data-rotulo=\"Risco\">Praticam menos e avançam menos.</td><td data-rotulo=\"Medida da escola\">Horário fixo na escola. Registro dos nomes pela direção.</td></tr><tr><td data-rotulo=\"Grupo\">Alunos com deficiência</td><td data-rotulo=\"Risco\">Barreiras de acesso e de compreensão.</td><td data-rotulo=\"Medida da escola\">Apoio do atendimento educacional especializado, mais tempo, acompanhamento de perto.</td></tr><tr><td data-rotulo=\"Grupo\">Alunos com muitas faltas</td><td data-rotulo=\"Risco\">Perdem as sessões na escola.</td><td data-rotulo=\"Medida da escola\">Busca ativa e retomada na volta.</td></tr><tr><td data-rotulo=\"Grupo\">Alunos com grande defasagem</td><td data-rotulo=\"Risco\">Desanimam diante de muitas habilidades a recuperar.</td><td data-rotulo=\"Medida da escola\">Metas curtas, conversa individual, reconhecimento de cada avanço.</td></tr><tr><td data-rotulo=\"Grupo\">Alunos recém-chegados</td><td data-rotulo=\"Risco\">Não conhecem a plataforma.</td><td data-rotulo=\"Medida da escola\">Acesso e explicação individual na primeira semana.</td></tr><tr><td data-rotulo=\"Grupo\">Famílias sem familiaridade com tecnologia</td><td data-rotulo=\"Risco\">Não acompanham.</td><td data-rotulo=\"Medida da escola\">Ajuda presencial no cadastro e informação por outros meios.</td></tr></tbody></table></div><h3>Perguntas que a gestão se faz todo mês</h3><ul class=\"chk\"><li><span></span>Sabemos quais alunos não têm acesso em casa?</li><li><span></span>Todos eles têm horário reservado na escola?</li><li><span></span>Há turmas com prática muito abaixo das outras? Por quê?</li><li><span></span>Os alunos com deficiência estão conseguindo usar?</li><li><span></span>Algum aluno foi cobrado ou exposto por não praticar?</li></ul><div class=\"nota alerta\"><b>Sem punição</b><br/>O reforço não é condição para recreio, passeio, merenda ou qualquer atividade. A falta de prática é um sinal para a escola agir, e não um motivo para punir o aluno.</div>"},{"id":"c24","titulo":"Perguntas frequentes da gestão","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td data-rotulo=\"Pergunta\">Quem cadastra os alunos?</td><td data-rotulo=\"Resposta\">A Secretaria, na implantação. A direção mantém as turmas atualizadas ao longo do ano.</td></tr><tr><td data-rotulo=\"Pergunta\">A coordenação precisa abrir o diagnóstico para o aluno estudar?</td><td data-rotulo=\"Resposta\">Não. O aluno é diagnosticado ao estudar. Abrir um diagnóstico para a rede serve para ter um retrato em uma data.</td></tr><tr><td data-rotulo=\"Pergunta\">O que é prática?</td><td data-rotulo=\"Resposta\">A proporção de alunos que estudaram no período.</td></tr><tr><td data-rotulo=\"Pergunta\">O que é recuperação?</td><td data-rotulo=\"Resposta\">As habilidades em que os alunos saíram de Ainda não ou Quase lá e chegaram a Domina.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso comparar turmas?</td><td data-rotulo=\"Resposta\">Para decidir onde apoiar, sim. Para fazer ranking, não.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso comparar professores?</td><td data-rotulo=\"Resposta\">Não. Os dados mostram a aprendizagem dos alunos, que depende de muitos fatores.</td></tr><tr><td data-rotulo=\"Pergunta\">Os responsáveis veem os dados de outros alunos?</td><td data-rotulo=\"Resposta\">Não. Cada responsável vê apenas os alunos ligados à conta dele.</td></tr><tr><td data-rotulo=\"Pergunta\">O aluno vê nota?</td><td data-rotulo=\"Resposta\">Não. Vê a própria evolução.</td></tr><tr><td data-rotulo=\"Pergunta\">O que fazer com um servidor que saiu?</td><td data-rotulo=\"Resposta\">Retirar as atribuições e pedir à Secretaria a desativação do acesso.</td></tr><tr><td data-rotulo=\"Pergunta\">Como mostrar a plataforma em reunião aberta?</td><td data-rotulo=\"Resposta\">Com dados de exemplo ou ocultando os nomes.</td></tr><tr><td data-rotulo=\"Pergunta\">Uma turma não aparece.</td><td data-rotulo=\"Resposta\">Verificar com a Secretaria se foi criada e se os alunos foram incluídos.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso exigir que os alunos estudem em casa?</td><td data-rotulo=\"Resposta\">Pode incentivar. Exigir prejudica quem não tem acesso.</td></tr></tbody></table></div>"},{"id":"c25","titulo":"Mais situações da gestão","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · o uso que caiu depois de um mês</div><p><b>Situação.</b> Na primeira semana, quase todos os alunos entraram. Um mês depois, menos da metade pratica.</p><p><b>O que fazer.</b></p><ol><li>Veja a prática por turma e encontre as que mais caíram.</li><li>Verifique se o horário na escola está sendo cumprido.</li><li>Converse com os professores dessas turmas.</li><li>Relance com os alunos: conversa em sala e meta da turma.</li><li>Envie mensagem às famílias com uma orientação simples.</li></ol><p><b>Resultado esperado.</b> A prática volta a subir e se estabiliza com a rotina.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a disputa pelos equipamentos</div><p><b>Situação.</b> Dois professores querem os equipamentos no mesmo horário, e uma turma fica semanas sem usar.</p><p><b>O que fazer.</b></p><ol><li>Monte a grade semanal com todos os professores.</li><li>Reserve horários de reposição.</li><li>Afixe a grade na sala dos professores.</li><li>Revise a cada bimestre.</li></ol><p><b>Resultado esperado.</b> Todas as turmas passam a ter horário garantido.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o professor que não abria o mapa</div><p><b>Situação.</b> Um professor experiente diz que conhece os alunos e não precisa do mapa.</p><p><b>O que fazer.</b></p><ol><li>Reconheça o conhecimento que ele tem da turma.</li><li>Peça que indique três alunos que preocupam.</li><li>Abram juntos o mapa e vejam o que ele mostra sobre esses alunos.</li><li>Pergunte se há algo no mapa que ele não esperava.</li><li>Combine uma consulta por semana, durante um mês.</li></ol><p><b>Resultado esperado.</b> O professor passa a usar o mapa como uma segunda opinião.</p></div><div class=\"pratica\"><div class=\"tt\">Para praticar · o plano da minha escola</div><div class=\"q\"><b>1.</b> Qual turma tem a menor prática hoje? O que você sabe sobre ela?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que ação você fará nesta semana?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Quem são os alunos sem acesso em casa e que horário eles têm na escola?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c26","titulo":"Anos iniciais e anos finais: o que muda","html":"<p>O reforço atende do 3º ao 9º ano. A forma de organizar o uso, de falar com os alunos e de envolver as famílias muda bastante entre os anos iniciais e os anos finais.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Aspecto</th><th>Anos iniciais (3º ao 5º)</th><th>Anos finais (6º ao 9º)</th></tr></thead><tbody><tr><td data-rotulo=\"Aspecto\">Autonomia do aluno</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Precisa de um adulto por perto para entrar, ler e manter o foco.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Usa sozinho, mas precisa de combinados e de acompanhamento do avanço.</td></tr><tr><td data-rotulo=\"Aspecto\">Duração da sessão</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Vinte minutos.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Trinta a quarenta minutos.</td></tr><tr><td data-rotulo=\"Aspecto\">Quem acompanha</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">O professor da turma, que vê todas as matérias.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Vários professores. Vale definir um professor de referência por turma.</td></tr><tr><td data-rotulo=\"Aspecto\">Leitura</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Alunos em consolidação da leitura podem precisar de apoio para ler os enunciados.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">A dificuldade de leitura aparece como erro em todas as matérias.</td></tr><tr><td data-rotulo=\"Aspecto\">Entrega dos acessos</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Colados na agenda, com aviso aos responsáveis.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Entregues ao aluno, com orientação sobre não emprestar.</td></tr><tr><td data-rotulo=\"Aspecto\">Família</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Costuma acompanhar de perto. Risco de responder pelo aluno.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Acompanha menos. Vale reforçar a conta do responsável e os avisos do professor.</td></tr><tr><td data-rotulo=\"Aspecto\">Motivação</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Reconhecimento imediato e metas do dia.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Conversa sobre o próprio avanço e sentido para o futuro.</td></tr><tr><td data-rotulo=\"Aspecto\">Defasagem</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Menor distância entre o ano e a base.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Lacunas acumuladas de vários anos. A volta à base é mais longa.</td></tr><tr><td data-rotulo=\"Aspecto\">Reunião pedagógica</td><td data-rotulo=\"Anos iniciais (3º ao 5º)\">Por ano, com todos os componentes.</td><td data-rotulo=\"Anos finais (6º ao 9º)\">Por área e por turma, para alinhar os professores.</td></tr></tbody></table></div><h3>O professor de referência nos anos finais</h3><ul><li>Olha o mapa da turma em todas as matérias, uma vez por semana.</li><li>Leva aos colegas os alunos que não praticam e as habilidades de base em falta.</li><li>Conversa com a turma sobre o avanço geral.</li><li>É o contato da turma com a coordenação.</li></ul><h3>A passagem do 5º para o 6º ano</h3><p>A mudança de um professor para vários costuma derrubar o rendimento. O histórico de aprendizagem acompanha o aluno, e os professores do 6º ano podem ver, desde o início, o que cada turma domina. Vale uma reunião entre os professores do 5º e do 6º ano para passar esse retrato.</p><div class=\"nota\"><b>Leitura é de todos</b><br/>Quando a habilidade prioritária é de leitura, o problema não é só de Língua Portuguesa. Todos os professores dos anos finais podem trabalhar a leitura de enunciados na própria disciplina.</div>"},{"id":"c27","titulo":"O painel mensal da escola","html":"<p>Uma página por mês, preenchida pela direção e pela coordenação, basta para acompanhar o reforço e prestar contas à equipe e à Secretaria.</p><div class=\"rapido\"><p><b>Escola:</b> ____________________ <b>Mês:</b> ____________________</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Indicador</th><th>Mês anterior</th><th>Este mês</th><th>O que explica</th></tr></thead><tbody><tr><td data-rotulo=\"Indicador\">Alunos que praticaram</td><td data-rotulo=\"Mês anterior\"> </td><td data-rotulo=\"Este mês\"></td><td data-rotulo=\"O que explica\"></td></tr><tr><td data-rotulo=\"Indicador\">Turmas com menor prática</td><td data-rotulo=\"Mês anterior\"> </td><td data-rotulo=\"Este mês\"></td><td data-rotulo=\"O que explica\"></td></tr><tr><td data-rotulo=\"Indicador\">Habilidades recuperadas</td><td data-rotulo=\"Mês anterior\"> </td><td data-rotulo=\"Este mês\"></td><td data-rotulo=\"O que explica\"></td></tr><tr><td data-rotulo=\"Indicador\">Três habilidades prioritárias</td><td data-rotulo=\"Mês anterior\"> </td><td data-rotulo=\"Este mês\"></td><td data-rotulo=\"O que explica\"></td></tr><tr><td data-rotulo=\"Indicador\">Responsáveis com conta</td><td data-rotulo=\"Mês anterior\"> </td><td data-rotulo=\"Este mês\"></td><td data-rotulo=\"O que explica\"></td></tr><tr><td data-rotulo=\"Indicador\">Alunos sem acesso em casa atendidos na escola</td><td data-rotulo=\"Mês anterior\"> </td><td data-rotulo=\"Este mês\"></td><td data-rotulo=\"O que explica\"></td></tr></tbody></table></div><p><b>O que funcionou neste mês:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que vamos mudar:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Ações do próximo mês (o quê, quem, até quando):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que precisamos da Secretaria:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div></div><h3>Como usar o painel</h3><ol class=\"passos\"><li>A direção preenche os números, com base nas telas de aprendizagem e de famílias.</li><li>A coordenação acrescenta as habilidades prioritárias.</li><li>Os dois conversam por quinze minutos sobre o que explica os números.</li><li>O painel é apresentado na reunião pedagógica, sem nomes de alunos.</li><li>As ações combinadas entram no quadro de encaminhamentos.</li><li>No mês seguinte, a conversa começa pelo que foi combinado.</li></ol><h3>Direção e coordenação: quem faz o quê</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Frequência</th><th>Direção</th><th>Coordenação pedagógica</th></tr></thead><tbody><tr><td data-rotulo=\"Frequência\">Toda semana</td><td data-rotulo=\"Direção\">Vê a prática por turma. Resolve acessos e horários.</td><td data-rotulo=\"Coordenação pedagógica\">Vê as habilidades prioritárias. Apoia um professor ou uma turma.</td></tr><tr><td data-rotulo=\"Frequência\">Todo mês</td><td data-rotulo=\"Direção\">Preenche o painel. Vê as famílias sem conta.</td><td data-rotulo=\"Coordenação pedagógica\">Leva o mapa a uma reunião pedagógica.</td></tr><tr><td data-rotulo=\"Frequência\">Todo bimestre</td><td data-rotulo=\"Direção\">Reunião com os responsáveis. Revisão da grade de uso.</td><td data-rotulo=\"Coordenação pedagógica\">Conselho de classe com os dados. Pauta de formação.</td></tr></tbody></table></div>"},{"id":"c28","titulo":"Erros comuns da gestão e como evitá-los","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Erro</th><th>O que acontece</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Erro\">Entregar os acessos e esperar que o uso aconteça</td><td data-rotulo=\"O que acontece\">Uso alto na primeira semana e queda depois.</td><td data-rotulo=\"O que fazer\">Horário fixo por turma e primeira sessão acompanhada.</td></tr><tr><td data-rotulo=\"Erro\">Deixar o reforço só para casa</td><td data-rotulo=\"O que acontece\">Praticam apenas os alunos com aparelho e internet.</td><td data-rotulo=\"O que fazer\">Garantir uso na escola para todos.</td></tr><tr><td data-rotulo=\"Erro\">Cobrar número sem olhar as condições</td><td data-rotulo=\"O que acontece\">Desânimo e atalhos.</td><td data-rotulo=\"O que fazer\">Verificar acesso, equipamento e horário antes de cobrar.</td></tr><tr><td data-rotulo=\"Erro\">Tratar o reforço como assunto da direção</td><td data-rotulo=\"O que acontece\">Os professores não usam o mapa.</td><td data-rotulo=\"O que fazer\">Levar o mapa às reuniões pedagógicas.</td></tr><tr><td data-rotulo=\"Erro\">Expor turmas e professores</td><td data-rotulo=\"O que acontece\">Defesa e resistência.</td><td data-rotulo=\"O que fazer\">Dados por turma nas reuniões, com foco no que fazer.</td></tr><tr><td data-rotulo=\"Erro\">Esquecer os responsáveis depois da primeira reunião</td><td data-rotulo=\"O que acontece\">As contas não são criadas ou deixam de ser usadas.</td><td data-rotulo=\"O que fazer\">Plano de comunicação ao longo do ano.</td></tr><tr><td data-rotulo=\"Erro\">Não atualizar turmas e alunos</td><td data-rotulo=\"O que acontece\">Professores não encontram alunos. Indicadores errados.</td><td data-rotulo=\"O que fazer\">Atualizar no mesmo dia cada entrada, saída e mudança.</td></tr><tr><td data-rotulo=\"Erro\">Usar o nível do aluno como nota</td><td data-rotulo=\"O que acontece\">O aluno passa a buscar acerto a qualquer custo.</td><td data-rotulo=\"O que fazer\">Manter o reforço sem nota.</td></tr><tr><td data-rotulo=\"Erro\">Punir quem não pratica</td><td data-rotulo=\"O que acontece\">O aluno associa o reforço a castigo.</td><td data-rotulo=\"O que fazer\">Entender o motivo e oferecer condições.</td></tr><tr><td data-rotulo=\"Erro\">Não comunicar erros e problemas</td><td data-rotulo=\"O que acontece\">O mesmo problema se repete em outras escolas.</td><td data-rotulo=\"O que fazer\">Registrar e informar a Secretaria.</td></tr><tr><td data-rotulo=\"Erro\">Mudar tudo a cada mês</td><td data-rotulo=\"O que acontece\">A equipe não cria rotina.</td><td data-rotulo=\"O que fazer\">Manter a grade e os combinados por um bimestre antes de rever.</td></tr></tbody></table></div><h3>Sinais de que a implantação vai bem</h3><ul class=\"chk\"><li><span></span>Toda turma tem horário de uso e ele é cumprido.</li><li><span></span>Os professores falam do mapa nas reuniões sem que a coordenação peça.</li><li><span></span>Os alunos sabem dizer em que habilidade estão.</li><li><span></span>A maioria dos responsáveis criou a conta.</li><li><span></span>A escola sabe o nome de cada aluno sem acesso em casa.</li><li><span></span>As habilidades prioritárias viraram tema de formação.</li><li><span></span>Ninguém foi exposto ou punido por causa do reforço.</li></ul>"},{"id":"c29","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td data-rotulo=\"Encontro\">1</td><td data-rotulo=\"Capítulos\">Do início até \"Como o aluno estuda\"</td><td data-rotulo=\"Perguntas para a conversa\">Como explicamos o reforço a um professor novo? E a um responsável?</td></tr><tr><td data-rotulo=\"Encontro\">2</td><td data-rotulo=\"Capítulos\">Os menus da coordenação e da direção e \"Organizar a escola\"</td><td data-rotulo=\"Perguntas para a conversa\">Cada um sabe usar as suas telas? O que falta organizar?</td></tr><tr><td data-rotulo=\"Encontro\">3</td><td data-rotulo=\"Capítulos\">De \"Como trazer os responsáveis\" até \"Rotina de acompanhamento\"</td><td data-rotulo=\"Perguntas para a conversa\">Quantos responsáveis já acompanham? Como lemos os indicadores?</td></tr><tr><td data-rotulo=\"Encontro\">4</td><td data-rotulo=\"Capítulos\">De \"As seis primeiras semanas\" até \"Como engajar os professores\"</td><td data-rotulo=\"Perguntas para a conversa\">A nossa grade de uso funciona? Que resistências encontramos?</td></tr><tr><td data-rotulo=\"Encontro\">5</td><td data-rotulo=\"Capítulos\">De \"Do dado à decisão\" até o final</td><td data-rotulo=\"Perguntas para a conversa\">Que decisão tomamos com base nos dados neste mês? Quem são os alunos sem acesso?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c30","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Quem liga o professor às turmas?</p><ol type=\"a\"><li>O próprio professor.</li><li>O responsável.</li><li>A coordenação, em Diagnósticos.</li><li>A direção, em Atribuições.</li></ol></div><div class=\"qz\"><p><b>2.</b> Muita prática com pouca recuperação de habilidades indica:</p><ol type=\"a\"><li>Problema de acesso.</li><li>Conteúdo difícil para a turma, possivelmente por pré-requisito.</li><li>Que a turma está no caminho.</li><li>Erro de cadastro.</li></ol></div><div class=\"qz\"><p><b>3.</b> A tela Habilidades prioritárias mostra:</p><ol type=\"a\"><li>Os responsáveis sem acesso.</li><li>As notas dos alunos.</li><li>As habilidades com mais alunos em Ainda não.</li><li>Os professores com menor desempenho.</li></ol></div><div class=\"qz\"><p><b>4.</b> Como o responsável recebe o acesso?</p><ol type=\"a\"><li>Pela escola, com kit impresso ou convite digital.</li><li>Pelo aluno, que cria a conta.</li><li>Pela Secretaria, por telefone.</li><li>Pela internet, sem a escola.</li></ol></div><div class=\"qz\"><p><b>5.</b> Qual uso dos indicadores respeita a ética?</p><ol type=\"a\"><li>Ranking de professores no mural.</li><li>Comparar cada turma com ela mesma ao longo do tempo.</li><li>Punir a turma que menos pratica.</li><li>Divulgar o retorno de um responsável.</li></ol></div><div class=\"qz\"><p><b>6.</b> Um servidor deixou a escola. O que fazer com o acesso dele?</p><ol type=\"a\"><li>Pedir a desativação à Secretaria.</li><li>Nada.</li><li>Deixar ativo.</li><li>Passar a senha ao substituto.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> d) A direção, em Atribuições. Sem a atribuição, o professor não vê as turmas.</p><p><b>2.</b> b) Conteúdo difícil para a turma, possivelmente por pré-requisito. Vale ver os pré-requisitos com o professor.</p><p><b>3.</b> c) As habilidades com mais alunos em Ainda não. É a lista do que a rede precisa retomar.</p><p><b>4.</b> a) Pela escola, com kit impresso ou convite digital. O acesso é oferecido pela escola.</p><p><b>5.</b> b) Comparar cada turma com ela mesma ao longo do tempo. Os dados servem para apoiar.</p><p><b>6.</b> a) Pedir a desativação à Secretaria. Acesso é pessoal e deve ser desativado.</p></div>"},{"id":"c31","titulo":"Glossário","html":"<dl><dt>Atribuição</dt><dd>Vínculo entre professor, turma e componente.</dd><dt>BNCC</dt><dd>Base Nacional Comum Curricular. Define as habilidades que o aluno deve desenvolver em cada ano e componente.</dd><dt>Componente curricular</dt><dd>Cada matéria do currículo: Língua Portuguesa, Matemática, Ciências e as demais.</dd><dt>Diagnóstico</dt><dd>Conjunto curto de questões que mostra quais habilidades o aluno já domina.</dd><dt>Habilidade</dt><dd>O que o aluno deve saber fazer. É a unidade que a plataforma acompanha.</dd><dt>Habilidade recuperada</dt><dd>Habilidade em que o aluno saiu de Ainda não ou Quase lá e chegou a Domina.</dd><dt>Kit de acesso</dt><dd>Folha individual com o código para o responsável entrar.</dd><dt>Nível de domínio</dt><dd>Situação do aluno em uma habilidade: Ainda não, Quase lá ou Domina.</dd><dt>Pré-requisito</dt><dd>Habilidade anterior que serve de base para outra.</dd><dt>Responsável</dt><dd>Adulto que cuida do aluno e o acompanha na plataforma.</dd><dt>Trilha</dt><dd>Sequência de estudo de uma habilidade, em cinco etapas.</dd><dt>Tutor</dt><dd>Apoio com inteligência artificial que orienta o aluno com perguntas e dicas.</dd></dl>"},{"id":"c32","titulo":"Guia rápido","html":"<div class=\"rapido\"><div class=\"duas\"><div><h3>Coordenação pedagógica</h3><ol class=\"passos\"><li><b>Habilidades prioritárias</b>: veja o que a rede precisa retomar.</li><li><b>Escolas e turmas</b>: veja quem pratica pouco.</li><li><b>Trilhas</b>: aprove o que está pendente.</li><li><b>Diagnósticos</b>: abra um novo a cada bimestre.</li></ol></div><div><h3>Direção escolar</h3><ol class=\"passos\"><li><b>Aprendizagem</b>: veja as turmas que não praticaram.</li><li><b>Famílias</b>: veja quem está sem responsável vinculado.</li><li><b>Acesso das famílias</b>: reenvie convites e kits.</li><li><b>Atribuições</b>: mantenha o quadro atualizado.</li></ol></div></div><h3>Lembre-se</h3><ul><li>Os dados servem para apoiar, não para punir.</li><li>Compare cada turma com ela mesma.</li><li>Aluno e responsável sem acesso não participam.</li><li>Dados de aluno não saem da plataforma.</li></ul></div>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"A primeira sessão de cada turma deve ser:","alternativas":["Em casa, sem orientação.","Acompanhada pelo professor e por um apoio da gestão.","Feita só pelos melhores alunos.","Adiada."],"correta":1,"explicacao":"Os problemas de acesso se resolvem na hora."},{"pergunta":"Um aluno esqueceu como entrar. A escola:","alternativas":["Gera novo acesso.","Espera o próximo ano.","Cria outro cadastro.","Empresta o acesso de um colega."],"correta":0,"explicacao":"Cada aluno usa o próprio acesso."},{"pergunta":"Um professor diz que o reforço é mais trabalho. A gestão:","alternativas":["Ignora.","Mostra que ele não aplica nem corrige e pede meia hora semanal para o mapa.","Obriga.","Retira a turma dele."],"correta":1,"explicacao":"Pedir pouco, com constância."},{"pergunta":"Pouca prática em uma turma leva a perguntar primeiro:","alternativas":["Se a turma é fraca.","Quem é o culpado.","Se os alunos têm acesso e horário na escola.","Qual será a punição."],"correta":2,"explicacao":"O acesso vem antes de tudo."},{"pergunta":"As habilidades prioritárias servem para:","alternativas":["Reprovar.","Fazer ranking de professores.","Definir a pauta de formação e a retomada.","Dar nota."],"correta":2,"explicacao":"Mostram onde concentrar esforço."},{"pergunta":"No conselho de classe, os dados do reforço:","alternativas":["Substituem as notas.","Não devem ser usados.","Decidem a aprovação.","Ajudam a ver o que a turma recuperou e o que retomar."],"correta":3,"explicacao":"Informam, não decidem."},{"pergunta":"Alunos sem internet em casa:","alternativas":["Têm horário reservado na escola.","São cobrados como os demais.","Perdem o recreio.","Ficam sem reforço."],"correta":0,"explicacao":"A escola garante o acesso."},{"pergunta":"Uma meta de prática muito pressionada pode gerar:","alternativas":["Menos trabalho.","Nenhum efeito.","Mais aprendizagem.","Atalhos, como responder pelo aluno."],"correta":3,"explicacao":"O objetivo é aprender, e não o número."}];
